#!/usr/bin/env python3
"""
Запуск на Railway:  python scripts/run_import.py
Встроенные данные — не требует загрузки xlsx.
"""
import base64, os, sys, tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

XLSX_B64 = ""

def main():
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(base64.b64decode(XLSX_B64))
        tmp_path = tmp.name
    try:
        from scripts.import_from_excel import run
        run(tmp_path, apply=True)
    finally:
        os.unlink(tmp_path)

if __name__ == "__main__":
    main()
